mapper.select:
SELECT c.id AS idColonia, c.nombre, c.codigo_postal AS codigoPostal, c.idMunicipio AS idMunicipio,
m.nombre AS nombreMunicipio, m.idEstado AS idEstado, e.nombre AS nombreEstado
FROM colonias c INNER JOIN municipios m ON c.idMunicipio = m.id INNER JOIN estados e ON m.idEstado = e.id WHERE c.codigo_postal = #{codigoPostal}
